// Engine tests: every fixture's output must match the real Swift compiler's
// recorded output (tests/fixtures/*.out, generated by tools/conformance.mjs).
import { describe, it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { run, runTests } from '../../src/engine/index.js';
import { parse } from '../../src/engine/parser.js';
import { tokenize } from '../../src/engine/lexer.js';
import { formatDouble, describe as describeValue, Dbl, NIL, Opt, SArray, copyValue, equals, hashKey, compare } from '../../src/engine/values.js';

const FIX = fileURLToPath(new URL('../fixtures/', import.meta.url));

describe('conformance with the real Swift compiler', () => {
  for (const f of fs.readdirSync(FIX).filter((x) => x.endsWith('.swift')).sort()) {
    it(f, async () => {
      const want = fs.readFileSync(path.join(FIX, f.replace(/\.swift$/, '.out')), 'utf8');
      const r = await run(fs.readFileSync(path.join(FIX, f), 'utf8'));
      if (want.includes('#ERROR')) {
        expect(r.error).toBeTruthy();
      } else {
        expect(r.error).toBeNull();
        expect(r.stdout.replace(/\s+$/, '')).toBe(want.replace(/\s+$/, ''));
      }
    });
  }
});

describe('compiler diagnostics match swiftc wording', () => {
  const cases = [
    ['let x = 5\nx = 6', "cannot assign to value: 'x' is a 'let' constant"],
    ['let a = 5\nlet b = 2.5\nprint(a + b)', "binary operator '+' cannot be applied to operands of type 'Int' and 'Double'"],
    ['print(y)', "cannot find 'y' in scope"],
    ['let n: Int? = 4\nprint(n + 1)', "value of optional type 'Int?' must be unwrapped"],
    ['struct P { var x = 0\n mutating func inc() { x += 1 } }\nlet p = P()\np.inc()', 'cannot use mutating member on immutable value'],
    ['func greet(name: String) { print(name) }\ngreet("Ana")', "missing argument label 'name:' in call"],
    ['func greet(_ name: String) { print(name) }\ngreet(name: "Ana")', "extraneous argument label 'name:' in call"],
    ['struct P { var x = 0 }\nlet p = P()\nprint(p.z)', "value of type 'P' has no member 'z'"],
    ['struct P { var x = 0 }\nlet p = P()\np.x = 3', "cannot assign to property: 'p' is a 'let' constant"],
    ['var s = "a"\ns = 5', "cannot assign value of type 'Int' to type 'String'"],
    ['let s = "abc"\nprint(s[0])', 'cannot subscript String with an Int'],
    ['let x: Int? = 3\nif x { }', "must be unwrapped to a value of type 'Bool'"],
  ];
  for (const [src, msg] of cases) {
    it(msg, async () => {
      const r = await run(src);
      expect(r.error?.message).toContain(msg);
      expect(r.error?.kind).toBe('compile');
      expect(r.stdout).toBe('');
    });
  }
});

describe('runtime traps', () => {
  it('index out of range keeps earlier output', async () => {
    const r = await run('print("before")\nlet a = [1]\nprint(a[3])');
    expect(r.stdout).toBe('before\n');
    expect(r.error.message).toBe('Fatal error: Index out of range');
    expect(r.error.line).toBe(3);
  });
  it('force unwrap of nil', async () => {
    const r = await run('let n: Int? = nil\nprint(n!)');
    expect(r.error.message).toMatch(/Unexpectedly found nil/);
  });
  it('division by zero', async () => {
    const r = await run('let z = 0\nprint(10 / z)');
    expect(r.error.message).toBe('Fatal error: Division by zero');
  });
  it('integer overflow', async () => {
    const r = await run('let m = Int.max\nprint(m + 1)');
    expect(r.error.message).toMatch(/overflow/);
  });
  it('infinite loops are stopped', async () => {
    const r = await run('var i = 0\nwhile true { i += 1 }', { maxSteps: 50000 });
    expect(r.error.kind).toBe('limit');
  });
  it('uncaught errors at top level', async () => {
    const r = await run('enum E: Error { case bad }\nthrow E.bad');
    expect(r.error.message).toMatch(/Error raised at top level/);
  });
  it('deep recursion reports stack overflow', async () => {
    const r = await run('func f(_ n: Int) -> Int { f(n + 1) }\nprint(f(0))');
    expect(r.error.kind).toBe('limit');
    expect(r.error.message).toMatch(/base case/);
  });
  it('fatalError message', async () => {
    const r = await run('fatalError("boom")');
    expect(r.error.message).toBe('Fatal error: boom');
  });
});

describe('language features', () => {
  const cases = [
    ['print(7 / 2, 7 % 2, 7.0 / 2, -7 / 2)', '3 1 3.5 -3'],
    ['print(0.1 + 0.2, 1e16, 0.00001, 100.0)', '0.30000000000000004 1e+16 1e-05 100.0'],
    ['let t = (x: 1, y: "a")\nprint(t, t.x, t.1)', '(x: 1, y: "a") 1 a'],
    ['var a = [1, 2]\nvar b = a\nb.append(3)\nprint(a, b)', '[1, 2] [1, 2, 3]'],
    ['class C { var v = 1 }\nlet c = C()\nlet d = c\nd.v = 9\nprint(c.v, c === d)', '9 true'],
    ['func f(_ x: inout Int) { x += 10 }\nvar n = 1\nf(&n)\nprint(n)', '11'],
    ['let r = [3, 1, 2].sorted(by: >)\nprint(r)', '[3, 2, 1]'],
    ['print([1, 2, 3].reduce(0, +), [1, 2, 3].map { $0 * $0 })', '6 [1, 4, 9]'],
    ['enum D: Int, CaseIterable { case a = 1, b, c }\nprint(D.allCases.map { $0.rawValue })', '[1, 2, 3]'],
    ['var s: Set = [1, 2]\ns.insert(2)\nprint(s.count)', '2'],
    ['let d = ["a": 1]\nprint(d["a", default: 0] + d["z", default: 5])', '6'],
    ['let x: Int? = nil\nprint(x ?? 7, x.map { $0 + 1 } ?? 0)', '7 0'],
    ['let words = ["a", "bb"]\nprint(words.map(\\.count))', '[1, 2]'],
    ['struct S { var n: Int\n  var double: Int { n * 2 }\n}\nprint(S(n: 4).double)', '8'],
    ['var log = [String]()\nstruct T { var v = 0 { didSet { print("now", v) } } }\nvar t = T()\nt.v = 3', 'now 3'],
    ['let s = "héllo"\nprint(s.count, s.uppercased())', '5 HÉLLO'],
    ['print(String(format: "%.2f|%5.1f|%03d", 3.14159, 2.25, 7))', '3.14|  2.2|007'],
    ['protocol P { func hi() -> String }\nextension P { func hi() -> String { "hi" } }\nstruct A: P {}\nprint(A().hi())', 'hi'],
    ['func g<T: Comparable>(_ a: T, _ b: T) -> T { a > b ? a : b }\nprint(g(3, 9), g("a", "b"))', '9 b'],
    ['let v = switch 5 { case 0..<3: "low"\ncase 3...: "high"\ndefault: "?" }\nprint(v)', 'high'],
  ];
  for (const [src, want] of cases) {
    it(src.split('\n')[0].slice(0, 50), async () => {
      const r = await run(src);
      expect(r.error).toBeNull();
      expect(r.stdout.trim()).toBe(want);
    });
  }
});

describe('concurrency on a virtual clock', () => {
  it('orders sleeping tasks by time', async () => {
    const r = await run(`func w(_ n: String, _ s: Int) async -> String {
    try? await Task.sleep(for: .seconds(s))
    print(n)
    return n
}
async let a = w("slow", 2)
async let b = w("fast", 1)
let all = await [a, b]
print(all)`);
    expect(r.stdout).toBe('fast\nslow\n["slow", "fast"]\n');
  });
});

describe('ARC and deinit', () => {
  it('frees objects without cycles and keeps cycles alive', async () => {
    const free = await run(`class A { deinit { print("A freed") } }\nvar a: A? = A()\na = nil\nprint("end")`);
    expect(free.stdout).toBe('A freed\nend\n');
    const cycle = await run(`class N { var other: N?\n deinit { print("freed") } }\nvar x: N? = N()\nvar y: N? = N()\nx!.other = y\ny!.other = x\nx = nil\ny = nil\nprint("end")`);
    expect(cycle.stdout).toBe('end\n');
  });
});

describe('step-through trace', () => {
  it('records lines and variables', async () => {
    const r = await run('var total = 0\nfor i in 1...3 {\n    total += i\n}\nprint(total)', { trace: true });
    expect(r.trace.length).toBeGreaterThan(4);
    expect(r.trace.some((t) => t.vars.total === '6' || t.vars.total === '3')).toBe(true);
  });
});

describe('Swift Testing runner', () => {
  it('reports passing and failing tests', async () => {
    const r = await runTests(`import Testing
func add(_ a: Int, _ b: Int) -> Int { a + b }
@Test func ok() { #expect(add(2, 2) == 4) }
@Test("Broken") func bad() { #expect(add(2, 2) == 5) }`);
    expect(r.results.map((t) => t.issues.length)).toEqual([0, 1]);
    expect(r.results[1].name).toBe('Broken');
  });
});

describe('lexer and parser', () => {
  it('tokenizes interpolation and raw strings', () => {
    const t = tokenize('let s = "a\\(b)c" + #"x\\n"#');
    expect(t.filter((k) => k.t === 'string').length).toBe(2);
  });
  it('reports syntax errors with a line', () => {
    expect(() => parse('let x = (1 + \n')).toThrow();
    expect(() => parse('func f( {')).toThrow(expect.objectContaining({ line: 1 }));
  });
  it('parses SwiftUI trailing closures and modifiers', () => {
    const ast = parse('VStack {\n Text("a")\n}\n.padding()');
    expect(ast.body.length).toBe(1);
  });
});

describe('value formatting', () => {
  it('formats doubles like Swift', () => {
    expect(formatDouble(3)).toBe('3.0');
    expect(formatDouble(1e-5)).toBe('1e-05');
    expect(formatDouble(Infinity)).toBe('inf');
    expect(formatDouble(-0)).toBe('-0.0');
  });
  it('describes collections and optionals', () => {
    expect(describeValue(new SArray(['a', 1]))).toBe('["a", 1]');
    expect(describeValue(new Opt(new Dbl(2)))).toBe('Optional(2.0)');
    expect(describeValue(NIL)).toBe('nil');
  });
  it('copies value types deeply', () => {
    const a = new SArray([new SArray([1])]);
    const b = copyValue(a);
    b.items[0].items.push(2);
    expect(a.items[0].items.length).toBe(1);
    expect(equals(new SArray([1, 2]), new SArray([1, 2]))).toBe(true);
    expect(hashKey(new SArray([1]))).toBe(hashKey(new SArray([1])));
    expect(compare('apple', 'banana')).toBe(-1);
  });
});

describe('beginner mistakes produce the same first error as swiftc', () => {
  const DIAG = fileURLToPath(new URL('../diagnostics/', import.meta.url));
  for (const f of fs.readdirSync(DIAG).filter((x) => x.endsWith('.swift')).sort()) {
    it(f, async () => {
      const want = fs.readFileSync(path.join(DIAG, f.replace(/\.swift$/, '.err')), 'utf8').trim();
      const r = await run(fs.readFileSync(path.join(DIAG, f), 'utf8'));
      expect(r.error).toBeTruthy();
      expect(r.error.message.startsWith(want.slice(0, 60))).toBe(true);
    });
  }
});

describe('review regressions', () => {
  it('an un-awaited async let still runs before its scope ends', async () => {
    const r = await run('var done = false\nfunc work() async -> Int { done = true; return 1 }\nfunc f() async { async let x: Int = work() }\nawait f()\nprint(done)');
    expect(r.stdout).toBe('true\n');
  });
  it('rejects redeclaring a constant', async () => {
    const r = await run('let x = 1\nlet x = 2');
    expect(r.error.message).toBe("invalid redeclaration of 'x'");
  });
  it('two programs running at once never mix output', async () => {
    const a = 'struct A: CustomStringConvertible { var description: String { print("A-side-effect"); return "A" } }\nprint(A())';
    const b = 'struct B: CustomStringConvertible { var description: String { "B" } }\nprint(B())';
    const [ra, rb] = await Promise.all([run(a), run(b)]);
    expect(ra.stdout).toBe('A-side-effect\nA\n');
    expect(rb.stdout).toBe('B\n');
  });
});

describe('review fixes: limits, values, captures', () => {
  it('empty infinite loops are stopped', async () => {
    for (const src of ['while true {}', 'repeat {} while true', 'for i in 0..<100000000 where i < 0 {}']) {
      const r = await run(src, { maxSteps: 20000 });
      expect(r.error?.kind).toBe('limit');
    }
  });
  it('rejects absurd allocations', async () => {
    const r = await run('let a = repeatElement(0, count: 1000000000)');
    expect(r.error?.message).toMatch(/out of range/);
    const p = await run('import Foundation\nprint("x".padding(toLength: 2, withPad: "", startingAt: 0))');
    expect(p.error?.message).toMatch(/NSInvalidArgumentException.*nil or empty padString/);
    expect(p.error?.kind).toBe('runtime');
  });
  it('coercion never changes the original value', async () => {
    const r = await run('let a = [1, 2]\nlet b: [Int?] = a\nprint(a)');
    expect(r.stdout).toBe('[1, 2]\n');
  });
  it('capture lists capture the value at creation', async () => {
    const r = await run('var x = 1\nlet f = { [x] in x }\nx = 2\nprint(f())');
    expect(r.stdout).toBe('1\n');
  });
  it('explicit .some and .none', async () => {
    const r = await run('let x: Int? = .some(3)\nlet y: Int? = .none\nprint(x!, y == nil)');
    expect(r.stdout).toBe('3 true\n');
  });
  it('inout writes survive a throw', async () => {
    const r = await run('enum E: Error { case x }\nfunc f(_ v: inout Int) throws { v = 7; throw E.x }\nvar n = 1\ndo { try f(&n) } catch { }\nprint(n)');
    expect(r.stdout).toBe('7\n');
  });
  it('dictionary keys with commas do not collide', async () => {
    const r = await run('var d: [[String]: Int] = [:]\nd[["a,sb", "c"]] = 1\nd[["a", "b,sc"]] = 2\nprint(d.count)');
    expect(r.stdout).toBe('2\n');
  });
  it('weak self is optional inside the closure', async () => {
    const r = await run('class M {\n    var n = 0\n    func make() -> () -> Void { { [weak self] in self?.n += 1 } }\n}\nlet m = M()\nlet f = m.make()\nf()\nf()\nprint(m.n)');
    expect(r.stdout).toBe('2\n');
  });
});

describe('review fixes: allocation, async let, weak captures', () => {
  it('charges bulk allocations against the step budget', async () => {
    const r = await run('let grid = Array(repeating: Array(repeating: 0, count: 100000), count: 100000)', { maxSteps: 1_000_000 });
    expect(r.error?.kind).toBe('limit');
  });
  it('joins async let children when the scope throws', async () => {
    const r = await run(`enum E: Error { case x }
func child() async -> Int {
    defer { print("child cleanup") }
    try? await Task.sleep(for: .seconds(1))
    return 1
}
func parent() async throws {
    async let c = child()
    throw E.x
}
do { try await parent() } catch { print("caught") }`);
    expect(r.stdout).toBe('child cleanup\ncaught\n');
  });
  it('weak captures become nil after deinit', async () => {
    const r = await run(`class T { deinit { print("deinit") } }
var x: T? = T()
let f = { [weak x] in print(x == nil) }
x = nil
f()`);
    expect(r.stdout).toBe('deinit\ntrue\n');
  });
  it('nested optionals hash distinctly', async () => {
    const r = await run('let s: Set<Int??> = [.none, .some(.none)]\nprint(s.count)');
    expect(r.stdout).toBe('2\n');
  });
  it('rejects tuple and async let redeclarations', async () => {
    expect((await run('let x = 1\nlet (x, y) = (2, 3)')).error?.message).toBe("invalid redeclaration of 'x'");
  });
});

describe('review fixes: overflow and tuple redeclaration', () => {
  it('huge nested allocations are refused before they happen', async () => {
    const r = await run('let a = Array(repeating: Array(repeating: 0, count: 2000), count: 2000000)');
    expect(r.error?.kind).toMatch(/limit|runtime/);
  });
  it('duplicate names inside one tuple pattern', async () => {
    expect((await run('let (a, a) = (1, 2)')).error?.message).toBe("invalid redeclaration of 'a'");
  });
});
